\begin{equation}
A(\gamma)=\frac{5.720\times0.847\times10^{7}}{2\left[1-\left(\frac{0.514}{\gamma}\right)+\left(\frac{0.228}{\gamma^{2}}\right)\right]}.
\end{equation}

